<?php
require_once __DIR__.'/../controllers/helpers.php';require_once __DIR__.'/../config/database.php';$user=requireRole(['etudiant']);$q=database()->prepare('SELECT ev.idEvaluation,ev.titre,ev.description,ev.dateLimite,m.idModule,m.libelle,de.fichier AS depot,de.dateDepot FROM evaluation ev JOIN module m ON m.idModule=ev.idModule JOIN semestre sm ON sm.idSemestre=m.idSemestre JOIN niveau n ON n.idNiveau=sm.idNiveau JOIN inscription i ON i.idNiveau=n.idNiveau JOIN dossier_etudiant d ON d.idDossier=i.idDossier LEFT JOIN depot de ON de.idEvaluation=ev.idEvaluation AND de.idEtudiant=d.idEtudiant WHERE d.idEtudiant=:id AND i.statut="VALIDEE" ORDER BY ev.dateLimite');$q->execute(['id'=>$user['id']]);$rows=$q->fetchAll();$pageTitle='Mes évaluations';$showSidebar=true;require __DIR__.'/../includes/header.php';?><h2>Mes évaluations</h2><div class="card"><table><tr><th>Évaluation</th><th>Module</th><th>Date limite</th><th>Dépôt</th></tr><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['titre'])?></td><td><?=htmlspecialchars('Module '.$row['idModule'].' - '.$row['libelle'])?></td><td><?=htmlspecialchars($row['dateLimite'])?></td><td><?=$row['depot']?'Déposé le '.htmlspecialchars($row['dateDepot']):'<a href="/etudiant/depot.php?idEvaluation='.(int)$row['idEvaluation'].'">Déposer</a>'?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">Aucune évaluation disponible.</td></tr><?php endif;?></table></div><?php require __DIR__.'/../includes/footer.php';?>